def forward(apps, schema_editor):
    CoreService = apps.get_model("inventory", "CoreService")
    ServiceImage = apps.get_model("inventory", "ServiceImage")
    ServiceImage.objects.exclude(role="").update(customization="context")
    for svc in CoreService.objects.all():
        if svc.managed_by:
            note = f"Managed by {svc.managed_by}."
            svc.description = f"{svc.description}\n{note}".strip() if note not in svc.description else svc.description
        routes = []
        for r in svc.nic1_routes or []:
            parts = str(r).replace(" via ", " ").split()
            if parts:
                routes.append({"nic": 1, "subnet": parts[0], **({"via": parts[1]} if len(parts) > 1 else {})})
        svc.routes = routes
        node = svc.nodes.order_by("name").first()
        if node is not None:
            svc.ssh_port, svc.ssh_secret = node.ssh_port, node.secret
        vyos_port = ((getattr(svc.site, "management", None) or {}).get("ports") or {}).get("vyos") if svc.site_id else None
        if svc.platform_id and vyos_port and svc.ssh_port == int(vyos_port):  # VyOS: on the site's VyOS port
            svc.image = ServiceImage.objects.filter(control__key=svc.platform.key, role="vyos").first()
        svc.save()


